import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.D7EuCHIT.js";const i=JSON.parse('{"title":"设置页挂载","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/settings-page.md","filePath":"plugins/settings-page.md","lastUpdated":1795367980000}'),a={name:"plugins/settings-page.md"};function r(T,d,E,A,I,_){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="设置页挂载" tabindex="-1">设置页挂载 <a class="header-anchor" href="#设置页挂载" aria-label="Permalink to &quot;设置页挂载&quot;">​</a></h1><p><code>LYRA_INTERFACE_SETTINGS_PAGE</code>（26，<code>plugin/settings_contracts.h</code>）让插件在宿主设置中挂载声明式页面。任何选中服务都可选实现；宿主枚举端点，不依赖私有名字。</p><h2 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>LYRA_SETTINGS_INFO</code>(1)</td><td>页面元数据：TITLE、ENTRY_TITLE、COUNT、PAGE、REVISION，可选 PROMPT/NOTICE/INPUT/ENTRY_PARENT/INLINE</td></tr><tr><td><code>LYRA_SETTINGS_ROW</code>(2)</td><td>按 INDEX 取行：TITLE、DETAIL/BUTTON、FLAGS、VALUE/MIN/MAX/STEP</td></tr><tr><td><code>LYRA_SETTINGS_OPEN</code>(3)</td><td>重置导航到 PAGE 0；宿主端点要求 HANDLE 字段</td></tr><tr><td><code>LYRA_SETTINGS_BACK</code>(4)</td><td>根页返回 UNSUPPORTED，否则 OK</td></tr><tr><td><code>LYRA_SETTINGS_ACTIVATE</code>(5)</td><td>按当前行 INDEX（可选 SECONDARY/VALUE）触发</td></tr><tr><td><code>LYRA_SETTINGS_CONFIRM</code>(6)</td><td>ACCEPT 解决当前 prompt；BACK 先取消 prompt</td></tr><tr><td><code>LYRA_SETTINGS_HOST_CAPABILITIES</code>(7)</td><td>宿主端点返回支持的行与 prompt FLAGS</td></tr></tbody></table><h2 id="行类型-flags" tabindex="-1">行类型（FLAGS） <a class="header-anchor" href="#行类型-flags" aria-label="Permalink to &quot;行类型（FLAGS）&quot;">​</a></h2><p><code>TOGGLE</code>(1)、<code>CHECKED</code>(2)、<code>DISABLED</code>(4)、<code>GROUP_END</code>(8)、<code>SLIDER</code>(16)、<code>FORWARD</code>(32)；HOST_CAPABILITIES 另返回 <code>CAN_EDIT_PROMPT</code>(64)、<code>CAN_ACTIVATE_PROMPT</code>(128)、<code>CAN_LEAD_TEXT</code>(256)、<code>CAN_LEAD_RGBA</code>(512)、<code>CAN_MOUNT_ROWS</code>(1024)。</p><h2 id="控件与状态" tabindex="-1">控件与状态 <a class="header-anchor" href="#控件与状态" aria-label="Permalink to &quot;控件与状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>声明</th><th>状态和事件</th></tr></thead><tbody><tr><td>说明行</td><td><code>TITLE</code>，可附 <code>DETAIL</code></td><td>用于呈现当前值或说明。只读内容可标记 <code>DISABLED</code></td></tr><tr><td>操作行</td><td><code>TITLE</code>，可附 <code>BUTTON</code></td><td>宿主用当前行 <code>INDEX</code> 发出 <code>ACTIVATE</code>。处理时按当前页面的行身份解析索引</td></tr><tr><td>导航行</td><td><code>FLAGS</code> 含 <code>FORWARD</code></td><td>宿主呈现进入子页的提示。插件处理 <code>ACTIVATE</code>、更新页面，并在 <code>INFO</code> 中返回新的 <code>PAGE</code> 和行数</td></tr><tr><td>开关</td><td><code>FLAGS</code> 含 <code>TOGGLE</code></td><td><code>CHECKED</code> 表示当前开启。插件处理激活并在下次读取时返回确认后的状态</td></tr><tr><td>滑块</td><td><code>FLAGS</code> 含 <code>SLIDER</code>，返回 <code>VALUE</code>、<code>MINIMUM</code>、<code>MAXIMUM</code>、<code>STEP</code></td><td>宿主显示拖动预览，激活消息可携带 <code>VALUE</code>。插件校验并持久化</td></tr><tr><td>分组边界</td><td>在最后一行加 <code>GROUP_END</code></td><td>与这一行的控件标记一起返回</td></tr><tr><td>前导图块</td><td>可选 <code>LEADING_TEXT</code> 或 <code>LEADING_RGBA</code></td><td>先检查对应能力位。像素数据为逐行紧密排列的预乘 RGBA，从顶部开始，图块边长由 <code>LYRA_SETTINGS_TILE_SIDE</code> 定义</td></tr><tr><td>确认提示</td><td><code>INFO</code> 返回 <code>PROMPT</code></td><td><code>CONFIRM</code> 用 <code>ACCEPT</code> 表示用户的确认结果。返回键先取消当前提示</td></tr><tr><td>单行输入提示</td><td>在确认提示中返回 <code>INPUT</code>，可以为空字符串</td><td>先检查 <code>CAN_EDIT_PROMPT</code>。确认时读取用户编辑后的 <code>INPUT</code></td></tr><tr><td>提示附加按钮</td><td><code>PROMPT_ACTION</code> 提供按钮文案</td><td>先检查 <code>CAN_ACTIVATE_PROMPT</code>。收到 <code>ACTIVATE_PROMPT</code> 时可处理独立操作，宿主保留输入草稿</td></tr></tbody></table><p>同一行可组合状态标记，例如 <code>TOGGLE | CHECKED | DISABLED</code>。插件仍应校验操作对应的页面、行身份和状态。页面内的说明或操作失败反馈可用 <code>NOTICE</code> 返回。</p><p>控件的字号、间距、开关观感和配色由宿主绘制，分布在 <code>settings</code> 与 <code>theme</code> 配置表。在 Android 窗口尺寸、方向或字体缩放改变时，宿主重新布局这些行。插件提供语义状态与文本，允许宿主根据可用宽度排版。<a href="/LyraPlayer-docs-site/config/reference/ui-settings">设置配置</a>、<a href="/LyraPlayer-docs-site/plugins/theming">主题与换肤</a>。</p><h2 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to &quot;约定&quot;">​</a></h2><ul><li>标量字段用 I64/F64，文本用含 NUL 的 UTF-8；数据借用至下一次 request；</li><li>未知必需字段拒绝，未知可选字段忽略；INFO 无副作用；</li><li><code>ENTRY_PARENT</code> 选择稳定的宿主分区路径，未知路径不回落首页；<code>INLINE</code> 非零时把根行内嵌到父页；</li><li>UI 负责滚动/滑块预览；插件负责校验、动作与持久化；</li><li>帧线程调用；CONFIRM 回显编辑后的 INPUT。</li></ul>',12)])])}const l=t(a,[["render",r]]);export{i as __pageData,l as default};
